import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']

from collections import Counter,deque
def transform(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; rect=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if seen[i][j] or g[i][j]==0: continue
            c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; q.append((ny,nx))
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            area=(y1-y0+1)*(x1-x0+1)
            if len(comp)>=4 and len(comp)/area>=0.6 and y1>y0 and x1>x0:
                for y in range(y0,y1+1):
                    for x in range(x0,x1+1):
                        rect[y][x]=True
    res=[row[:] for row in g]
    nonrect=Counter(g[i][j] for i in range(H) for j in range(W) if not rect[i][j])
    bg=nonrect.most_common(1)[0][0]
    for i in range(H):
        for j in range(W):
            if not rect[i][j]: res[i][j]=bg
    return res
